def transform_pattern(grid):
    n_rows = len(grid)
    output = []

    # For N rows, output uses 3 blocks: reverse, forward, reverse
    for block in range(3):
        if block == 0 or block == 2:  # Reverse order
            for r in range(n_rows - 1, -1, -1):
                row_vals = [grid[r][c] for c in range(len(grid[0]))]
                output.append(row_vals[::-1] + row_vals)
        else:  # Block 1: Forward order
            for r in range(n_rows):
                row_vals = [grid[r][c] for c in range(len(grid[0]))]
                output.append(row_vals[::-1] + row_vals)

    return output

